package greeter

import "strings"

// Slug 把 s 归一成小写连字符形式的 slug：
// 去掉首尾空白，连续空白折成一个 "-"。
func Slug(s string) string {
	return strings.ToLower(strings.Join(strings.Fields(s), "-"))
}

package greeter

import "testing"

func TestSlug(t *testing.T) {
	cases := []struct {
		in   string
		want string
	}{
		{"Hello World", "hello-world"},
		{"  Hello World  ", "hello-world"},
		{"a   b", "a-b"},
	}
	for _, c := range cases {
		if got := Slug(c.in); got != c.want {
			t.Errorf("Slug(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}

package greeter

import "strings"

// JoinSlug 把每个片段 Slug 化后用 "/" 连接，跳过空串与纯空白片段。
func JoinSlug(parts ...string) string {
	slugs := make([]string, 0, len(parts))
	for _, p := range parts {
		if s := Slug(p); s != "" {
			slugs = append(slugs, s)
		}
	}
	return strings.Join(slugs, "/")
}

package greeter

import "testing"

func TestJoinSlug(t *testing.T) {
	cases := []struct {
		in   []string
		want string
	}{
		{[]string{"Hello World", "Big Day"}, "hello-world/big-day"},
		{[]string{"a", "", "b"}, "a/b"},
		{[]string{"a", "   ", "b"}, "a/b"},
	}
	for _, c := range cases {
		if got := JoinSlug(c.in...); got != c.want {
			t.Errorf("JoinSlug(%q) = %q, want %q", c.in, got, c.want)
		}
	}
}
